      "Sõnumid kahe inimese vahel, tõlgitud kummagi keelde.",
      "Sina kirjutad oma keeles, teine loeb enda omas.",
      "Grupis: COMMUNITY ruumides.",
      "Kõned, kus sinu laused ilmuvad teisele tõlgituna.",
      "Sinu kõne muutub kohe tõlgitud tekstiks.",
      "Võimalik on ka päris hääl, krüpteeritult, telefonist telefoni.",
      "Videokõned kahekesi, tõlgitud lausetega.",
      "Kaamera lülitub sisse ainult siis, kui sina otsustad.",
      "Kaks inimest, kaks keelt, üks telefon teie vahel.",
      "Mõlemale oma mikrofon, tõlge mõlemas suunas.",
      "Originaaltekst ja tõlge ekraanil, loetakse ette, kui telefon lubab.",
      "Keeled valitakse käsitsi: automaatset tuvastamist veel pole. Mikrofon sõltub brauserist.",
      "Pildista dokumenti, silti või menüüd: loe seda oma keeles.",
      "Foto või galeriipilt, loetakse telefonis, tuvastatud teksti saab parandada.",
      "Foto ei lahku kunagi sinu telefonist: tõlkijale läheb ainult tuvastatud tekst.",
      "Dokumendi keel valitakse käsitsi. Kopeerimine, jagamine ja hoiatused ebakindla lugemise korral: veel mitte.",
      "Avalikud ruumid: igaüks kirjutab oma keeles, igaüks loeb enda omas.",
      "Otseülekanded sinu keeles, tõlgitud subtiitritega.",
      "Praegu kuni 12 vaatajat ühe otseülekande kohta.",
      "Tunnid, harjutused ja edusammud valitud keeles.",
      "Tõlgitud kuulutused, riikide kaubandusreeglid, toll ja rahatööriistad.",
      "Riikide hädaabinumbrid ja kasulikud tõlgitud laused, mida näidata või valjult esitada.",
      "Hädaolukorras helista kõigepealt hädaabiteenistusse.",
      "Puuduta maailma piirkonda: selle keeled, reisilaused, keegi, kellele kirjutada.",
      "Kellele?",
      "Kõigile, kõikjal maailmas",
      "Eraisikud",
      "Räägi pere ja sõpradega üle kogu maailma.",
      "Reisijad",
      "Ole mõistetud kõikjal, ka kodust kaugel.",
      "Turistid",
      "Loe menüüd või silti, küsi teed.",
      "Üliõpilased",
      "Suhtle teiste riikidega ja harjuta keelt.",
      "Õpetajad",
      "Too keel klassis ellu päris suhtlusega.",
      "Ettevõtted",
      "Räägi klientide ja tarnijatega nende keeles.",
      "Ühingud",
