      "ການແປອັດຕະໂນມັດ: ຄຸນນະພາບແຕກຕ່າງກັນຕາມພາສາ. ພາສາທີ່ມີຄົນເວົ້າຫຼາຍທີ່ສຸດແມ່ນໜ້າເຊື່ອຖືທີ່ສຸດ.",
      "ເພື່ອຫຍັງ?",
      "ການໃຊ້ງານຈິງ, ທຸກມື້",
      "ການທ່ອງທ່ຽວ",
      "ການພົບປະ",
      "ຮູ້ຈັກຜູ້ຄົນຈາກປະເທດອື່ນດ້ວຍຄວາມໝັ້ນໃຈ. ກຳລັງກະກຽມ.",
      "ໄວໆນີ້",
      "ວຽກ",
      "ການຊ່ວຍເຫຼືອກັນ",
      "ສຳລັບທຸລະກິດ",
      "ລົມກັບລູກຄ້າຂອງທ່ານທົ່ວໂລກເປັນພາສາຂອງເຂົາ: ໂຮງແຮມ, ອົງການ, ຮ້ານຄ້າອອນລາຍ, ນຳເຂົ້າ-ສົ່ງອອກ.",
      "ຄົ້ນພົບຂໍ້ສະເໜີ Pro",
      "ເປັນສ່ວນໜຶ່ງຂອງໂລກທີ່ເປີດກວ້າງ, ມີມະນຸດສະທຳ ແລະ ເຊື່ອມຕໍ່ກັນຫຼາຍຂຶ້ນ.",
      "ສ້າງບັນຊີຟຣີຂອງຂ້ອຍ",
      "ລອງໃຊ້",
      "ແຕະເມືອງໜຶ່ງເທິງໜ່ວຍໂລກ",
      "ຊອກຫາພາສາ",
      "ປຶ້ມບັນທຶກການຄົ້ນພົບຂອງທ່ານ",
      "ພາສາທີ່ຄົ້ນພົບໃນອຸປະກອນນີ້:",
      "ລຶບ",
      "ເກັບໄວ້ໃນອຸປະກອນນີ້ເທົ່ານັ້ນ. ບໍ່ມີຫຍັງຖືກສົ່ງອອກ.",
      "ບໍ່ພົບພາສາ",
      "ຢຸດຊົ່ວຄາວ",
      "ສືບຕໍ່",
      "ແຕະພາສາໜຶ່ງເພື່ອລອງໃນການສາທິດ.",
      "ໂລກດຽວ. ທຸກພາສາ. ການເຊື່ອມຕໍ່ດຽວ.",
      "ລະບົບນິເວດ",
      "ສິບເອັດພື້ນທີ່, ບັນຊີດຽວ",
      "ທຸກພື້ນທີ່ເປີດດ້ວຍບັນຊີຟຣີ. ສະຖານະທີ່ສະແດງແມ່ນສະຖານະຈິງ.",
      "ເປີດ",
      "ລອງການສາທິດ",
      "ຍັງບໍ່ທັນ",
      "ຂໍ້ຄວາມລະຫວ່າງສອງຄົນ, ແປເປັນພາສາຂອງແຕ່ລະຄົນ.",
      "ທ່ານຂຽນເປັນພາສາຂອງທ່ານ, ອີກຝ່າຍອ່ານເປັນພາສາຂອງເຂົາ.",
      "ເປັນກຸ່ມ: ໃນຫ້ອງ COMMUNITY.",
      "ການໂທທີ່ປະໂຫຍກຂອງທ່ານປາກົດເປັນຄຳແປໃຫ້ອີກຝ່າຍ.",
      "ຄຳເວົ້າຂອງທ່ານກາຍເປັນຂໍ້ຄວາມທີ່ແປແລ້ວທັນທີ.",
      "ສຽງແທ້ກໍເປັນໄປໄດ້, ເຂົ້າລະຫັດ, ຈາກໂທລະສັບຫາໂທລະສັບ.",
      "ການໂທວິດີໂອສອງຄົນ, ພ້ອມປະໂຫຍກທີ່ແປແລ້ວ.",
      "ກ້ອງຈະເປີດເມື່ອທ່ານຕັດສິນໃຈເທົ່ານັ້ນ.",
      "ສອງຄົນ, ສອງພາສາ, ໂທລະສັບໜ່ວຍດຽວຢູ່ລະຫວ່າງທ່ານ.",
      "ໄມໂຄຣໂຟນສຳລັບແຕ່ລະຄົນ, ແປທັງສອງທາງ.",
      "ຂໍ້ຄວາມຕົ້ນສະບັບ ແລະ ຄຳແປເທິງໜ້າຈໍ, ອ່ານອອກສຽງຖ້າໂທລະສັບອະນຸຍາດ.",
      "ເລືອກພາສາດ້ວຍມື: ຍັງບໍ່ມີການກວດຫາອັດຕະໂນມັດ. ໄມໂຄຣໂຟນຂຶ້ນກັບບຣາວເຊີ.",
      "ຖ່າຍຮູບເອກະສານ, ປ້າຍ ຫຼື ລາຍການອາຫານ: ອ່ານເປັນພາສາຂອງທ່ານ.",
      "ຮູບຖ່າຍ ຫຼື ຮູບຈາກຄັງຮູບ, ອ່ານໃນໂທລະສັບ, ແກ້ໄຂຂໍ້ຄວາມທີ່ຮັບຮູ້ໄດ້.",
      "ຮູບບໍ່ເຄີຍອອກຈາກໂທລະສັບຂອງທ່ານ: ມີແຕ່ຂໍ້ຄວາມທີ່ຮັບຮູ້ໄດ້ເທົ່ານັ້ນທີ່ໄປຫາຕົວແປ.",
      "ເລືອກພາສາຂອງເອກະສານດ້ວຍມື. ການສຳເນົາ, ການແບ່ງປັນ ແລະ ຄຳເຕືອນເມື່ອອ່ານບໍ່ແນ່ນອນ: ຍັງບໍ່ທັນ.",
      "ຫ້ອງສາທາລະນະ: ທຸກຄົນຂຽນເປັນພາສາຂອງຕົນ, ທຸກຄົນອ່ານເປັນພາສາຂອງຕົນ.",
      "ການຖ່າຍທອດສົດທີ່ຕິດຕາມໄດ້ເປັນພາສາຂອງທ່ານ, ພ້ອມຄຳບັນຍາຍທີ່ແປແລ້ວ.",
      "ຕອນນີ້ສູງສຸດ 12 ຜູ້ຊົມຕໍ່ການຖ່າຍທອດສົດ.",
      "ບົດຮຽນ, ແບບຝຶກຫັດ ແລະ ຄວາມກ້າວໜ້າໃນພາສາທີ່ທ່ານເລືອກ.",
      "ປະກາດທີ່ແປແລ້ວ, ກົດລະບຽບການຄ້າຕາມປະເທດ, ພາສີ ແລະ ເຄື່ອງມືດ້ານເງິນ.",
      "ເບີສຸກເສີນຕາມປະເທດ ແລະ ປະໂຫຍກທີ່ເປັນປະໂຫຍດທີ່ແປແລ້ວ, ເພື່ອສະແດງ ຫຼື ເປີດໃຫ້ຟັງ.",
      "ໃນກໍລະນີສຸກເສີນ, ໃຫ້ໂທຫາໜ່ວຍບໍລິການສຸກເສີນກ່ອນ.",
      "ແຕະພາກພື້ນໜຶ່ງຂອງໂລກ: ພາສາຂອງມັນ, ປະໂຫຍກສຳລັບການເດີນທາງ, ຄົນທີ່ຈະຂຽນຫາ.",
      "ສຳລັບໃຜ?",
      "ສຳລັບທຸກຄົນ, ທຸກບ່ອນໃນໂລກ",
      "ບຸກຄົນທົ່ວໄປ",
      "ລົມກັບຄອບຄົວ ແລະ ໝູ່ເພື່ອນທົ່ວໂລກ.",
      "ນັກເດີນທາງ",
      "ໃຫ້ຄົນເຂົ້າໃຈທຸກບ່ອນ, ເຖິງແມ່ນຈະຢູ່ໄກບ້ານ.",
      "ນັກທ່ອງທ່ຽວ",
      "ອ່ານລາຍການອາຫານ ຫຼື ປ້າຍ, ຖາມທາງ.",
      "ນັກຮຽນນັກສຶກສາ",
