      "ສະມາຄົມ",
      "ລວມສະມາຊິກທີ່ບໍ່ເວົ້າພາສາດຽວກັນເຂົ້າກັນ.",
      "ມືອາຊີບ",
      "ໂຮງແຮມ, ໄກດ໌, ຮ້ານຄ້າ: ບໍລິການລູກຄ້າທຸກຄົນເປັນພາສາຂອງເຂົາ.",
      "ຜູ້ສ້າງສັນ",
      "ດຳເນີນການຖ່າຍທອດສົດທີ່ມີຜູ້ຕິດຕາມຫຼາຍພາສາ.",
      "ອົງການສາກົນ",
      "ຊ່ວຍໃຫ້ທີມທີ່ໃຊ້ພາສາຕ່າງກັນເຮັດວຽກຮ່ວມກັນ.",
      "ຄູ່ຮ່ວມງານ",
      "ສ້າງບໍລິການສຳລັບທົ່ວໂລກຮ່ວມກັບ ONE WORLD.",
      "ໂອກາດ",
      "ສິ່ງທີ່ເປັນໄປໄດ້ເມື່ອອຸປະສັກທາງພາສາໝົດໄປ",
      "ການທ່ອງທ່ຽວສາກົນ",
      "ການຄ້າ",
      "ການສຶກສາ",
      "ການສື່ສານດ້ານວິຊາຊີບ",
      "ການຮ່ວມມືສາກົນ",
      "ອົງການຊຸມຊົນ",
      "ການແລກປ່ຽນວັດທະນະທຳ",
      "ຜູ້ສ້າງເນື້ອຫາ",
      "ບໍລິການດ້ານພາສາ",
      "ການເປັນຄູ່ຮ່ວມງານສາກົນ",
      "ຮູບແບບທຸລະກິດ",
      "ຟຣີສຳລັບທຸກຄົນ, ພ້ອມຂໍ້ສະເໜີສຳລັບຜູ້ທີ່ຕ້ອງການຫຼາຍກວ່າ",
      "ມີໃຫ້ໃຊ້ມື້ນີ້",
      "ແອັບຟຣີ",
      "ຂໍ້ຄວາມ, ການໂທ ແລະ ການແປ, ບໍ່ຕ້ອງສະໝັກແບບເສຍເງິນ.",
      "ຂໍ້ສະເໜີສຳລັບທຸລະກິດ, ເງື່ອນໄຂຢູ່ໜ້າ Pro.",
      "ລິ້ງຄູ່ຮ່ວມງານ",
      "ການເດີນທາງ ແລະ ບໍລິການ: ພວກເຮົາອາດໄດ້ຮັບຄ່ານາຍໜ້າ, ໂດຍທ່ານບໍ່ເສຍຄ່າເພີ່ມ.",
      "ຂໍ້ສະເໜີສຳລັບອະນາຄົດ",
      "ຍັງບໍ່ໄດ້ສະເໜີ. ຍັງບໍ່ມີການກຳນົດລາຄາ.",
      "ການສະໝັກສະມາຊິກສຳລັບທຸລະກິດ",
      "ຂໍ້ສະເໜີ Enterprise",
      "ໃບອະນຸຍາດດ້ານການສຶກສາ",
      "ການເປັນຄູ່ຮ່ວມງານ",
      "ບໍລິການເສີມ",
      "ງານກິດຈະກຳ ແລະ ບໍລິການມືອາຊີບ",
      "ຄວາມໄວ້ວາງໃຈ",
      "ຂໍ້ມູນຂອງທ່ານ: ສິ່ງທີ່ໄດ້ກວດສອບແລ້ວ",
